import DiyCarouselPreview from '@/components/content/DiyCarouselPreview.vue';
import { apiDiyAuthorHotWords, type DiyAuthorChoice } from '@/api/diyAuthorOptions';
import { canonicalPresentationReference, presentationPreviewForReference, presentationPreviewUrl } from '@/utils/diyPresentationEditor';
import { navigationDocument, navigationRecord as record, navRead as read, navArray, navText as text, navNumber as number, navFlag as flag, navSet, navigationColor } from '@/utils/diyNavigationEditor';
import { carouselOrdinal as ordinal, carouselLabels, carouselKind, carouselEntries, addCarousel, moveCarousel, newCarouselItem, setCarouselTabTarget, carouselLinkPath, setCarouselLink, canonicalCarouselBlock, canonicalNavigationImage, type CarouselRecord, type ModernCarouselKind } from '@/utils/diyCarouselEditor';
const props=withDefaults(defineProps<{modelValue:string;editorKey:string;disabled?:boolean;pageId?:number;pagePublished?:boolean}>(),{disabled:false,pageId:0,pagePublished:false}),emit=defineEmits<{'update:modelValue':[value:string]}>(),auth=useAuthStore();
const modernNames=['swiperBg','homeComb'] as const,labels=carouselLabels,addKind=ref<ModernCarouselKind>('swiperBg'),selected=ref(-1),slideIndex=ref(0),tabIndex=ref(0),wordIndex=ref(0),revision=ref(0),error=ref(''),previews=ref<Record<string,string>>({}),hotWords=ref<Array<{id:number;name:string}>>([]),hotLoading=ref(false),hotError=ref(''),previewLoading=ref(false);
let alive=true,hotAbort:AbortController|null=null,previewAbort:AbortController|null=null,lastCommitted='';
const actor=()=>`${auth.token}:${auth.userInfo?.id}:${auth.userInfo?.level}:${auth.uniqueAuth.join(',')}:${getToken()}:${localStorage.getItem('admin_session')}`;
function editableNow(){return alive&&!props.disabled&&!!auth.token&&auth.token===getToken()&&!!auth.userInfo&&(auth.userInfo.level===0||auth.uniqueAuth.includes('dise.manage'));}
const canEdit=computed(()=>{void revision.value;return editableNow();}),canChooseMedia=computed(()=>canEdit.value&&!!auth.userInfo&&(auth.userInfo.level===0||auth.uniqueAuth.includes('attachment.view')));
const parsed=computed(()=>{try{return{value:navigationDocument(props.modelValue),error:''};}catch(reason){return{value:null,error:reason instanceof Error?reason.message:'装修 JSON 无效'};}}),document=computed(()=>parsed.value.value),entries=computed(()=>carouselEntries(document.value??[])),block=computed(()=>record(document.value?.[selected.value])),kind=computed(()=>carouselKind(block.value?.name)),layout=computed(()=>ordinal(read(block.value,['styleConfig','tabVal']),kind.value==='homeComb'?0:1,2));
const slides=computed(()=>navArray(block.value,['swiperConfig','list'])),tabs=computed(()=>navArray(block.value,['tabListConfig','list'])),words=computed(()=>navArray(block.value,['hotWords','list'])),slide=computed(()=>record(slides.value[slideIndex.value])),tab=computed(()=>record(tabs.value[tabIndex.value])),word=computed(()=>record(words.value[wordIndex.value]));
watch(entries,()=>{if(!entries.value.some(e=>e.index===selected.value)){selected.value=entries.value[0]?.index??-1;slideIndex.value=tabIndex.value=wordIndex.value=0;}},{immediate:true});
const slideTitle=computed(()=>text(read(slide.value,kind.value==='swiperBg'?['imgTitle']:['info',0,'value']))),slideLink=computed(()=>kind.value?text(read(slide.value,carouselLinkPath(kind.value,slide.value))):''),tabType=computed(()=>ordinal(read(tab.value,['dataType','tabVal']),0,1)),tabDestination=computed(()=>{const t=record(read(tab.value,[tabType.value===1?'classPage':'microPage']));return t?.id?`${text(t.name)} #${String(t.id)}`:'尚未选择真实目标';});
const stamp=()=>({actor:actor(),editor:props.editorKey,raw:props.modelValue,revision:revision.value,index:selected.value,slide:slideIndex.value,tab:tabIndex.value,word:wordIndex.value});
const current=(s:ReturnType<typeof stamp>)=>alive&&editableNow()&&s.actor===actor()&&s.editor===props.editorKey&&s.raw===props.modelValue&&s.revision===revision.value&&s.index===selected.value&&s.slide===slideIndex.value&&s.tab===tabIndex.value&&s.word===wordIndex.value;
function invalidate(clearCatalog=false){revision.value++;hotAbort?.abort();previewAbort?.abort();hotAbort=previewAbort=null;hotLoading.value=previewLoading.value=false;previews.value={};if(clearCatalog){hotWords.value=[];hotError.value='';}}
watch(()=>props.modelValue,()=>invalidate(),{flush:'sync'});watch(()=>[props.editorKey,props.disabled],()=>{invalidate(true);selected.value=entries.value[0]?.index??-1;slideIndex.value=tabIndex.value=wordIndex.value=0;},{flush:'sync'});watch(()=>`${auth.token}:${auth.userInfo?.id}:${auth.userInfo?.level}:${auth.uniqueAuth.join(',')}`,()=>invalidate(true),{flush:'sync'});
function invalidateSession(){invalidate(true);}window.addEventListener('admin-session-changed',invalidateSession);window.addEventListener('admin-auth-expired',invalidateSession);window.addEventListener('storage',invalidateSession);onBeforeUnmount(()=>{alive=false;invalidate(true);window.removeEventListener('admin-session-changed',invalidateSession);window.removeEventListener('admin-auth-expired',invalidateSession);window.removeEventListener('storage',invalidateSession);});
function commit(value:unknown[]){if(!editableNow())return false;try{const raw=JSON.stringify(value,null,2);navigationDocument(raw);lastCommitted=raw;invalidate();emit('update:modelValue',raw);error.value='';return true;}catch(reason){error.value=reason instanceof Error?reason.message:'不能完整保存';return false;}}
function edit(change:(row:CarouselRecord)=>void){if(!editableNow()||!document.value||!block.value||!kind.value)return false;try{const value=structuredClone(document.value),row=record(value[selected.value]);if(!row)return false;change(row);return commit(value);}catch(reason){error.value=reason instanceof Error?reason.message:'当前字段无法修改';return false;}}
function select(value:unknown){if(typeof value==='number'&&entries.value.some(e=>e.index===value)){invalidate();selected.value=value;slideIndex.value=tabIndex.value=wordIndex.value=0;}}
function add(){if(!document.value)return;try{const result=addCarousel(document.value,addKind.value);if(commit(result.value)){selected.value=result.selected;slideIndex.value=tabIndex.value=wordIndex.value=0;}}catch(reason){error.value=reason instanceof Error?reason.message:'无法添加';}}
function remove(){if(!document.value||!kind.value)return;const value=structuredClone(document.value);value.splice(selected.value,1);if(commit(value))selected.value=-1;}
function move(direction:number){if(!document.value)return;try{const result=moveCarousel(document.value,selected.value,direction);if(commit(result.value))selected.value=result.selected;}catch(reason){error.value=reason instanceof Error?reason.message:'不能移动';}}
function setLeaf(path:Array<string|number>,value:unknown){return edit(row=>navSet(row,path,value));}
function setVisible(value:unknown){if(typeof value==='boolean')setLeaf(['isHide'],!value);}
function setEnabled(value:unknown){if(block.value?.isShow!==undefined&&typeof value==='boolean')setLeaf(['isShow'],value);}
function textLimit(value:unknown,normal:number){return Math.max(normal,[...text(value)].length);}
function setText(path:Array<string|number>,value:unknown,normal:number){if(typeof value==='string'&&[...value].length<=textLimit(read(block.value,path),normal))setLeaf(path,value);}
type ListKind='slides'|'tabs'|'words';
const listPath=(list:ListKind)=>[list==='slides'?'swiperConfig':list==='tabs'?'tabListConfig':'hotWords','list'];
const listRows=(list:ListKind)=>list==='slides'?slides.value:list==='tabs'?tabs.value:words.value;
const listIndex=(list:ListKind)=>list==='slides'?slideIndex:list==='tabs'?tabIndex:wordIndex;
function selectList(list:ListKind,value:unknown){if(typeof value==='number'&&Number.isInteger(value)&&value>=0&&value<listRows(list).length){invalidate();listIndex(list).value=value;}}
function addList(list:ListKind){const k=kind.value;if(!k||k==='swipers'||list!=='slides'&&k!=='homeComb'||listRows(list).length>=(list==='slides'?10:list==='tabs'?100:20))return;const at=listRows(list).length;if(edit(row=>{const items=structuredClone(navArray(row,listPath(list)));items.push(newCarouselItem(k,list));navSet(row,listPath(list),items);}))listIndex(list).value=at;}
function copyLegacySlide(){if(kind.value!=='swipers'||!slide.value||slides.value.length>=10)return;const at=slides.value.length,copy=structuredClone(slide.value);if(edit(row=>{const items=structuredClone(navArray(row,['swiperConfig','list']));items.push(copy);navSet(row,['swiperConfig','list'],items);}))slideIndex.value=at;}
function removeList(list:ListKind){if(list!=='slides'&&kind.value!=='homeComb')return;const at=listIndex(list).value;if(at<0||at>=listRows(list).length)return;if(edit(row=>{const items=structuredClone(navArray(row,listPath(list)));items.splice(at,1);navSet(row,listPath(list),items);}))listIndex(list).value=Math.max(0,at-1);}
function moveList(list:ListKind,direction:number){if(list!=='slides'&&kind.value!=='homeComb')return;const from=listIndex(list).value,to=from+direction;if(![-1,1].includes(direction)||to<0||to>=listRows(list).length)return;if(edit(row=>{const items=structuredClone(navArray(row,listPath(list)));[items[from],items[to]]=[items[to],items[from]];navSet(row,listPath(list),items);}))listIndex(list).value=to;}
function setSlideTitle(value:unknown){if(!slide.value)return;setText(['swiperConfig','list',slideIndex.value,...(kind.value==='swiperBg'?['imgTitle']:['info',0,'value'])],value,kind.value==='swiperBg'?100:4);}
