async function loadHotWords(){if(!editableNow()||kind.value!=='homeComb')return;hotAbort?.abort();const issued=stamp(),controller=new AbortController();hotAbort=controller;hotLoading.value=true;hotError.value='';try{const list=await apiDiyAuthorHotWords(controller.signal);if(current(issued)&&!controller.signal.aborted)hotWords.value=list;}catch(reason){if(current(issued))hotError.value=reason instanceof Error?reason.message:'平台热词读取失败';}finally{if(hotAbort===controller){hotAbort=null;hotLoading.value=false;}}}
type ImageRole='slide'|'logo';
function imageReference(role:ImageRole){return text(role==='logo'?kind.value==='homeComb'?read(block.value,['logoConfig','url']):'':read(slide.value,['img']));}
function imagePreview(role:ImageRole){const raw=imageReference(role);return presentationPreviewForReference(raw,previews.value[canonicalPresentationReference(raw)])||presentationPreviewUrl(raw);}
function setImage(role:ImageRole,value:string){if(role==='logo'&&kind.value==='homeComb')return edit(row=>navSet(row,['logoConfig','url'],canonicalNavigationImage(value)));if(role==='slide'&&slide.value)return edit(row=>navSet(row,['swiperConfig','list',slideIndex.value,'img'],canonicalNavigationImage(value)));return false;}
const previewLease=computed(()=>{const issued=stamp();return()=>current(issued);});
const mediaSessions=computed(()=>{const make=(role:ImageRole)=>{const issued=stamp(),key=`${props.editorKey}:${revision.value}:${selected.value}:${slideIndex.value}:${role}`,actorAtIssue=actor(),editor=props.editorKey;return{key,choose:async(reference:string,signed:string)=>{if(!current(issued)||!canChooseMedia.value)return;const approved=presentationPreviewForReference(reference,signed),index=selected.value,slot=slideIndex.value;if(!setImage(role,reference))return;const expected=lastCommitted;await nextTick();if(alive&&editableNow()&&canChooseMedia.value&&actor()===actorAtIssue&&props.editorKey===editor&&selected.value===index&&slideIndex.value===slot&&props.modelValue===expected&&canonicalPresentationReference(imageReference(role))===canonicalPresentationReference(reference)&&approved)previews.value={[canonicalPresentationReference(reference)]:approved};}};};return{slide:make('slide'),logo:make('logo')};});
const slideSession=computed(()=>{const issued=stamp();return{key:`${props.editorKey}:${revision.value}:${selected.value}:${slideIndex.value}:slide-link`,choose:(choice:DiyAuthorChoice)=>{if(current(issued)&&choice&&typeof choice.url==='string')edit(row=>setCarouselLink(row,slideIndex.value,choice.url));}};});
const tabSession=computed(()=>{const issued=stamp();return{key:`${props.editorKey}:${revision.value}:${selected.value}:${tabIndex.value}:tab`,choose:(choice:DiyAuthorChoice)=>{if(current(issued)&&kind.value==='homeComb'&&choice?.selection?.kind===(tabType.value===1?'category':'micro'))edit(row=>setCarouselTabTarget(row,tabIndex.value,choice.selection!));}};});
function clearLink(){edit(row=>setCarouselLink(row,slideIndex.value,''));}
const enumFields=computed(()=>{const f=(key:string,label:string,options:string[],fallback=0,slot='tabVal')=>({key,label,options,fallback,slot}),legacy=kind.value==='swipers';return legacy?[f('tabConfig','旧版展示方式',['静态广告','轮播'],1),f('docConfig','旧版指示器',['圆形','方形'],0,'type'),f('imgConfig','旧版图片圆角',['圆角','直角'],0,'type')]:[f('styleConfig','轮播风格',kind.value==='homeComb'?['样式一','样式二']:['样式一','样式二','样式三'],kind.value==='homeComb'?0:1),...(kind.value==='homeComb'?[f('classConfig','轮播分类显示',['显示分类','隐藏分类']),f('searchConfig','轮播搜索位置',['普通搜索','吸顶搜索'])]:[]),f('docConfig','轮播指示器样式',['圆点','伸缩圆点','进度条','短线']),f('docPosition','轮播指示器位置',['左对齐','居中','右对齐'],1),f('toneConfig','轮播色调',['跟随主题','自定义'])];});
function setEnum(key:string,value:unknown){const f=enumFields.value.find(f=>f.key===key);if(f&&typeof value==='number'&&Number.isInteger(value)&&value>=0&&value<f.options.length)setLeaf([key,f.slot],value);}
interface ColourField{key:string;label:string;fallback:string;index:number}
const colourFields=computed(()=>{const f=(key:string,label:string,fallback:string,index=0):ColourField=>({key,label,fallback,index});return kind.value==='swipers'?[]:[...(kind.value==='homeComb'?[f('classColor','轮播分类渐变起始色','#E93323'),f('classColor','轮播分类渐变结束色','#E93323',1)]:[f('bgColor','轮播背景颜色','#F62C2C')]),...(ordinal(read(block.value,['toneConfig','tabVal']),0,1)===1?[f('dotColor','轮播选中指示器颜色','#E93323'),f('dotBgColor','轮播未选中指示器颜色','#DDDDDD')]:[])];});
function colour(f:ColourField){return navigationColor(read(block.value,[f.key,'color',f.index,'item']),f.fallback);}
function setColour(f:ColourField,value:unknown){if(typeof value==='string'&&colourFields.value.some(field=>field.key===f.key&&field.index===f.index)&&navigationColor(value,'')===value.trim())setLeaf([f.key,'color',f.index,'item'],value.trim());}
const lengthFields=computed(()=>kind.value==='homeComb'?[{key:'contentConfig',label:'轮播分类间距（px）',fallback:20}]:kind.value==='swipers'?[{key:'itemEdge',label:'旧版左右露边（rpx）',fallback:0},{key:'lrConfig',label:'旧版左右边距（rpx）',fallback:0},{key:'mbConfig',label:'旧版页面上间距（rpx）',fallback:0}]:[{key:'topConfig',label:'轮播上内边距（设计 px）',fallback:10},...(layout.value!==1?[{key:'bottomConfig',label:'轮播下内边距（设计 px）',fallback:10}]:[]),{key:'prConfig',label:'轮播左右内边距（设计 px）',fallback:10},{key:'mbConfig',label:'轮播页面上间距（设计 px）',fallback:0},...(layout.value===2?[{key:'imgConfig',label:'轮播图片间隙（设计 px）',fallback:10}]:[])]);
function setLength(key:string,value:unknown){if(lengthFields.value.some(f=>f.key===key)&&typeof value==='number'&&Number.isFinite(value)&&value>=0&&value<=100)setLeaf([key,'val'],value);}
const radiusSeparate=computed(()=>flag(read(block.value,['filletImg','type']))&&Array.isArray(read(block.value,['filletImg','valList']))&&navArray(block.value,['filletImg','valList']).length===4?1:0);
function radiusPath(index:number):Array<string|number>{const order=kind.value==='homeComb'?[0,1,2,3]:[0,1,3,2];return radiusSeparate.value?['filletImg','valList',order[index]!, 'val']:['filletImg','val'];}
function setRadiusType(value:unknown){if(kind.value&&kind.value!=='swipers'&&(value===0||value===1))setLeaf(['filletImg','type'],value);}
function setRadius(index:number,value:unknown){if(kind.value&&kind.value!=='swipers'&&typeof value==='number'&&Number.isFinite(value)&&value>=0&&value<=Number.MAX_SAFE_INTEGER/2)setLeaf(radiusPath(index),value);}
function mediaPairs(row:CarouselRecord){const pairs=slides.value.map((r,i)=>({reference:text(read(r,['img'])),preview:read(row,['swiperConfig','list',i,'img'])}));if(kind.value==='homeComb')pairs.push({reference:imageReference('logo'),preview:read(row,['logoConfig','url'])});return pairs;}
async function loadSavedPreviews(){if(!editableNow()||!block.value||!props.pageId||!props.pagePublished)return;previewAbort?.abort();const issued=stamp(),controller=new AbortController(),id=props.pageId,expected=JSON.stringify(canonicalCarouselBlock(block.value));previewAbort=controller;previewLoading.value=true;previews.value={};error.value='';try{const response=await fetch(`/api/diy/get_diy/${id}`,{credentials:'omit',cache:'no-store',signal:controller.signal}),body=record(await response.json()),data=record(body?.data);if(!current(issued)||props.pageId!==id||!props.pagePublished||controller.signal.aborted)return;if(!response.ok||body?.status!==200||!Array.isArray(data?.value))throw Error('公开轮播预览暂不可用');const found=data.value.map(record).find(row=>row&&JSON.stringify(canonicalCarouselBlock(row))===expected);if(!found)throw Error('当前轮播与已发布内容不同，请保存后再读取');const next:Record<string,string>={};for(const pair of mediaPairs(found)){const approved=presentationPreviewForReference(pair.reference,pair.preview);if(approved)next[canonicalPresentationReference(pair.reference)]=approved;}previews.value=next;}catch(reason){if(current(issued))error.value=reason instanceof Error?reason.message:'轮播图片预览失败';}finally{if(previewAbort===controller){previewAbort=null;previewLoading.value=false;}}}
</script>
<style scoped>
.carousel-author-editor{display:grid;gap:12px;width:100%;padding:14px;border:1px solid var(--el-border-color);border-radius:8px;box-sizing:border-box;min-width:0}.hint{margin:0;font-size:12px;color:var(--el-text-color-secondary);line-height:1.7}.toolbar{display:flex;flex-wrap:wrap;gap:8px}.toolbar .el-select{width:170px}.fields{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:0 16px}.fields :deep(.el-select),.fields :deep(.el-input-number){width:100%}.stored{overflow-wrap:anywhere;width:100%;font-size:12px;color:var(--el-text-color-secondary)}.media-field{display:flex;gap:8px;flex-wrap:wrap;align-items:center}.media-field>img{width:72px;height:60px;object-fit:contain;border:1px solid var(--el-border-color)}.media-field>.stored{flex-basis:100%;margin:0}@media(max-width:620px){.fields{grid-template-columns:1fr}}
</style>
